typedef long long ll;

typedef struct Edge {
    int to, next;
} Edge;

static int cmp_ll(const void *a, const void *b) {
    ll x = *(const ll *)a;
    ll y = *(const ll *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    ll *A = (ll *)malloc((N + 1) * sizeof(ll));
    for (int i = 1; i <= N; i++) scanf("%lld", &A[i]);

    int M = 2 * (N - 1);
    Edge *edges = (Edge *)malloc(M * sizeof(Edge));
    int *head = (int *)malloc((N + 1) * sizeof(int));
    for (int i = 1; i <= N; i++) head[i] = -1;

    int ecnt = 0;
    for (int i = 0; i < N - 1; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        edges[ecnt].to = v;
        edges[ecnt].next = head[u];
        head[u] = ecnt++;
        edges[ecnt].to = u;
        edges[ecnt].next = head[v];
        head[v] = ecnt++;
    }

    int *parent = (int *)malloc((N + 1) * sizeof(int));
    int *order = (int *)malloc(N * sizeof(int));
    int *stack = (int *)malloc(N * sizeof(int));
    int top = 0, ordsz = 0;

    stack[top++] = 1;
    parent[1] = 0;
    while (top) {
        int v = stack[--top];
        order[ordsz++] = v;
        for (int e = head[v]; e != -1; e = edges[e].next) {
            int to = edges[e].to;
            if (to == parent[v]) continue;
            parent[to] = v;
            stack[top++] = to;
        }
    }

    ll *sum = (ll *)malloc((N + 1) * sizeof(ll));
    int *hasNeg = (int *)malloc((N + 1) * sizeof(int));
    int *dp = (int *)malloc((N + 1) * sizeof(int));

    ll *childSums = (ll *)malloc((N + 1) * sizeof(ll));

    for (int idx = N - 1; idx >= 0; idx--) {
        int v = order[idx];
        sum[v] = A[v];
        hasNeg[v] = (A[v] < 0);

        int childCnt = 0;
        int base = 0;

        for (int e = head[v]; e != -1; e = edges[e].next) {
            int u = edges[e].to;
            if (u == parent[v]) continue;

            sum[v] += sum[u];
            hasNeg[v] |= hasNeg[u];
            base += dp[u];
            childSums[childCnt++] = sum[u];
        }

        if (!hasNeg[v] || sum[v] < 0) {
            dp[v] = 0;
            continue;
        }

        qsort(childSums, childCnt, sizeof(ll), cmp_ll);

        ll cur = A[v];
        int keep = 0;
        for (int i = 0; i < childCnt; i++) {
            if (cur + childSums[i] < 0) {
                cur += childSums[i];
                keep++;
            } else {
                break;
            }
        }

        dp[v] = base + (childCnt - keep);
    }

    printf("%d\n", dp[1]);

    free(A);
    free(edges);
    free(head);
    free(parent);
    free(order);
    free(stack);
    free(sum);
    free(hasNeg);
    free(dp);
    free(childSums);

    return 0;
}

