// Returns: {min_cuts_if_negative, min_cuts_if_all_positive, sum_of_negative_component}
// For all_positive case, sum is just the sum of positive values
pair<long long, pair<long long, long long>> dfs(int v, int p) {
    parent[v] = p;

    // dp_neg: min cuts for negative sum component
    // dp_pos: min cuts for all-positive component  
    // sum_neg: total sum if we go for negative component
    // sum_pos: total sum if we go for all-positive component

    long long dp_neg = 0, dp_pos = 0;
    long long sum_neg = A[v], sum_pos = A[v];

    // If A[v] is negative, we cannot have all-positive component
    if (A[v] < 0) {
        dp_pos = INF;
        sum_pos = -INF;
    }

    vector<pair<long long, pair<long long, long long>>> child_results;

    for (int u : adj[v]) {
        if (u == p) continue;
        auto res = dfs(u, v);
        long long child_neg = res.first;
        long long child_pos = res.second.first;
        long long child_sum_neg = res.second.second;

        // Option 1: cut the edge
        long long cut_cost = 1 + min(child_neg, child_pos);

        // Option 2: keep the edge (child joins our component)
        long long keep_cost = min(child_neg, child_pos);
        // Actually, we need to be more careful about keeping

        child_results.push_back({cut_cost, {keep_cost, child_sum_neg}});
    }

    // For negative component: we can either cut all children or keep some
    // If we keep a child, that child's component must also be negative
    // Total sum must be negative

    // Let's compute optimal way to have negative total sum
    // Start with cutting all children
    long long total_cuts = 0;
    long long total_sum = A[v];
    vector<pair<long long, long long>> keep_options; // {savings, child_sum}

    for (auto& res : child_results) {
        long long cut_cost = res.first;
        long long keep_cost = res.second.first;
        long long child_sum = res.second.second;

        total_cuts += cut_cost;
        // If we keep instead of cut, we save (cut_cost - keep_cost) cuts
        // but add child_sum to total_sum
        if (keep_cost < INF && child_sum < 0) {
            keep_options.push_back({cut_cost - keep_cost, child_sum});
        }
    }

    // Sort by savings descending, and try to add children to make sum negative
    sort(keep_options.begin(), keep_options.end(), 
         [](auto& a, auto& b) { return a.first > b.first; });

    long long best_neg = total_cuts;
    long long best_sum = total_sum;

    // If we can already have negative sum with all cut
    if (total_sum < 0) {
        best_neg = total_cuts;
        best_sum = total_sum;
    } else {
        // Try to add children to make sum negative
        long long cur_sum = total_sum;
        long long cur_cuts = total_cuts;
        bool found = false;

        for (auto& opt : keep_options) {
            cur_sum += opt.second;
            cur_cuts -= opt.first;
            if (cur_sum < 0) {
                if (cur_cuts < best_neg) {
                    best_neg = cur_cuts;
                    best_sum = cur_sum;
                }
                found = true;
            }
        }

        if (!found) {
            // Cannot make this component negative while keeping v
            // We need to cut v from its parent, so this is still valid
            best_neg = total_cuts;
            best_sum = total_sum;
        }
    }

    // For all-positive component: all values must be positive
    long long best_pos = INF;
    if (A[v] > 0) {
        total_cuts = 0;
        total_sum = A[v];

        for (auto& res : child_results) {
            long long cut_cost = res.first;
            long long keep_cost = res.second.first;
            long long child_sum = res.second.second;

            // For all-positive, we can only keep children that are all-positive
            // and have positive sum
            if (child_sum > 0 && keep_cost < INF) {
                total_cuts += keep_cost;
                total_sum += child_sum;
            } else {
                total_cuts += cut_cost;
            }
        }
        best_pos = total_cuts;
    }

    return {best_neg, {best_pos, best_sum}};
}

