    int N;
    cin >> N;

    vector<int64> A(N + 1);
    for (int i = 1; i <= N; ++i) cin >> A[i];

    vector<vector<int>> g(N + 1);
    for (int i = 0; i < N - 1; ++i) {
        int u, v;
        cin >> u >> v;
        g[u].push_back(v);
        g[v].push_back(u);
    }

    vector<int> parent(N + 1, 0), order;
    order.reserve(N);
    stack<int> st;
    st.push(1);
    parent[1] = -1;
    while (!st.empty()) {
        int v = st.top();
        st.pop();
        order.push_back(v);
        for (int to : g[v]) {
            if (to == parent[v]) continue;
            parent[to] = v;
            st.push(to);
        }
    }

    // dp0[v]: minimum cuts inside subtree of v so that the component containing v
    //         (within the remaining subtree) is "bad" and has no computer.
    // dp1[v]: minimum cuts inside subtree of v so that the component containing v
    //         is "bad" and has at least one computer.
    //
    // For dp1 we need to know the sum of the kept component containing v, because
    // it must be negative. We keep the best (minimum cuts) for each possible sum.
    //
    // Since sums can be large, we compress by dominance:
    // For fixed cut count, keep the maximum sum achievable.
    // Then after each merge, compress states so that for increasing cuts, sums are strictly increasing.
    //
    // Finally dp1[v] = minimum cuts among states with sum < 0 and hasComputer = true.

    const int INF = 1e9;

    vector<int> dp0(N + 1, INF), ans1(N + 1, INF);

    // For each node, states for components containing v and having at least one computer:
    // vector of (cuts, maxSum)
    vector<vector<pair<int,int64>>> states(N + 1);

    for (int idx = N - 1; idx >= 0; --idx) {
        int v = order[idx];

        // Initial component only v
        int cur0 = INF;
        vector<pair<int,int64>> cur1;

        if (A[v] > 0) {
            cur0 = 0; // only batteries
        } else {
            cur1.push_back({0, A[v]}); // has computer, sum = A[v] < 0
        }

        for (int to : g[v]) {
            if (to == parent[v]) continue;

            int childBad = min(dp0[to], ans1[to]);

            int new0 = INF;
            vector<pair<int,int64>> new1;

            // Option 1: cut edge (v,to)
            if (cur0 < INF && childBad < INF) new0 = min(new0, cur0 + childBad + 1);
            for (auto [c, s] : cur1) {
                if (childBad < INF) new1.push_back({c + childBad + 1, s});
            }

            // Option 2: keep edge, child's root component merges into v's component
            // child can contribute a no-computer bad component (dp0) or a computer-containing component (states[to])
            if (cur0 < INF) {
                // merge cur0 with child dp0 -> still no computer
                if (dp0[to] < INF) new0 = min(new0, cur0 + dp0[to]);

                // merge cur0 with child states -> now has computer
                for (auto [cc, ss] : states[to]) {
                    new1.push_back({cur0 + cc, A[v] + 0 + ss - A[v]}); // just cur sum implicit as A[v]+merged positives
                }
            }

            // To correctly track sums for cur0 states, note cur0 only possible when current merged component has no computer,
            // hence all included nodes have positive A. We need its sum to merge later with computer components.
            // So cur0 alone is insufficient. We need exact sum for no-computer component too.
            // Let's rebuild with one scalar because if no computer, keeping more positive sum is always better for later
            //? Actually for achieving negative after merging with computers, smaller sum is better.
            // Therefore we also need the minimum sum for each cut count. Simpler: unify all states with flag hasComputer.

            // Since above approach is flawed, we stop and switch to a correct DP below.
        }
    }

    // Correct DP:
    // For each node v, maintain two maps:
    //   pos[cuts] = minimum possible sum of component containing v with NO computer
    //   neg[cuts] = minimum possible sum of component containing v with >=1 computer
    // We only care about minimum sum for each cuts, because smaller sum is always better
    // for eventually making sum negative.
    //
    // At the end:
    //   valid no-computer states are always acceptable.
    //   valid computer states require sum < 0.
    //
    // We'll recompute from scratch.

    vector<map<int,int64>> pos(N + 1), neg(N + 1);
    vector<int> best(N + 1, INF);

    for (int idx = N - 1; idx >= 0; --idx) {
        int v = order[idx];

        map<int,int64> curPos, curNeg;
        if (A[v] > 0) curPos[0] = A[v];
        else curNeg[0] = A[v];

        for (int to : g[v]) {
            if (to == parent[v]) continue;

            map<int,int64> nxtPos, nxtNeg;

            int childBest = best[to];

            // cut edge
            for (auto [c1, s1] : curPos) {
                if (childBest < INF) {
                    int nc = c1 + childBest + 1;
                    auto it = nxtPos.find(nc);
                    if (it == nxtPos.end() || s1 < it->second) nxtPos[nc] = s1;
                }
            }
            for (auto [c1, s1] : curNeg) {
                if (childBest < INF) {
                    int nc = c1 + childBest + 1;
                    auto it = nxtNeg.find(nc);
                    if (it == nxtNeg.end() || s1 < it->second) nxtNeg[nc] = s1;
                }
            }

            // keep edge: merge with child pos
            for (auto [c1, s1] : curPos) {
                for (auto [c2, s2] : pos[to]) {
                    int nc = c1 + c2;
                    int64 ns = s1 + s2;
                    auto it = nxtPos.find(nc);
                    if (it == nxtPos.end() || ns < it->second) nxtPos[nc] = ns;
                }
                for (auto [c2, s2] : neg[to]) {
                    int nc = c1 + c2;
                    int64 ns = s1 + s2;
                    auto it = nxtNeg.find(nc);
                    if (it == nxtNeg.end() || ns < it->second) nxtNeg[nc] = ns;
                }
            }
            for (auto [c1, s1] : curNeg) {
                for (auto [c2, s2] : pos[to]) {
                    int nc = c1 + c2;
                    int64 ns = s1 + s2;
                    auto it = nxtNeg.find(nc);
                    if (it == nxtNeg.end() || ns < it->second) nxtNeg[nc] = ns;
                }
                for (auto [c2, s2] : neg[to]) {
                    int nc = c1 + c2;
                    int64 ns = s1 + s2;
                    auto it = nxtNeg.find(nc);
                    if (it == nxtNeg.end() || ns < it->second) nxtNeg[nc] = ns;
                }
            }

            // prune dominated states:
            // for same/larger cuts, if sum is not smaller, it's useless.
            auto prune = [&](map<int,int64>& mp) {
                vector<pair<int,int64>> vec(mp.begin(), mp.end());
                mp.clear();
                int64 bestSum = (1LL<<62);
                for (auto [c, s] : vec) {
                    if (s < bestSum) {
                        mp[c] = s;
                        bestSum = s;
                    }
                }
            };
            prune(nxtPos);
            prune(nxtNeg);

            curPos.swap(nxtPos);
            curNeg.swap(nxtNeg);
        }

        pos[v].swap(curPos);
        neg[v].swap(curNeg);

        best[v] = INF;
        for (auto [c, s] : pos[v]) best[v] = min(best[v], c);
        for (auto [c, s] : neg[v]) if (s < 0) best[v] = min(best[v], c);
    }

    cout << best[1] << '\n';
    return 0;
}

