            int u = Integer.parseInt(st.nextToken());
            int v = Integer.parseInt(st.nextToken());
            tree[u].add(v);
            tree[v].add(u);
        }

        dp_off = new long[N + 1];
        dp_on = new long[N + 1];
        sum_on = new long[N + 1];
        hasComp = new boolean[N + 1];

        dfs(1, 0);

        long ans = Math.min(dp_off[1], dp_on[1]);
        System.out.println(ans);
    }

    static void dfs(int v, int p) {
        // Initialize as single node component
        long totalSum = A[v];
        boolean hasComputer = (A[v] < 0);
        long cutCost = 0; // cost if we cut all children edges

        // For dp_on we may keep some children merged (disabled ones)
        // We'll compute best by deciding per child cut or keep
        long bestOff = 0; // dp_off for v based on decisions
        long bestOnSum = A[v];
        boolean bestOnHasComp = hasComputer;
        long bestOnCost = 0;

        for (int u : tree[v]) {
            if (u == p) continue;
            dfs(u, v);

            long cut = Math.min(dp_off[u], dp_on[u]) + 1;
            long keep = dp_off[u]; // we can only keep if child component is disabled

            // For off state: we can either cut or keep
            bestOff += Math.min(cut, keep);

            // For on state: we must keep only disabled children merged
            bestOnCost += keep;
            bestOnSum += sum_on[u];
            bestOnHasComp |= hasComp[u];
        }

        // dp_off[v]: component is disabled (no computer OR sum < 0)
        // Option 1: no computer in component
        if (!bestOnHasComp) {
            dp_off[v] = bestOnCost;
        } else {
            // Option 2: sum < 0
            if (bestOnSum < 0) {
                dp_off[v] = bestOnCost;
            } else {
                dp_off[v] = bestOff; // must cut at least something to make it disabled
            }
        }

        // dp_on[v]: component active (sum >= 0 and has computer)
        if (bestOnSum >= 0 && bestOnHasComp) {
            dp_on[v] = bestOnCost;
        } else {
            dp_on[v] = INF;
        }

        // Also consider possibility: cut all children and be single node active
        long singleCutCost = 0;
        for (int u : tree[v]) {
            if (u == p) continue;
            singleCutCost += Math.min(dp_off[u], dp_on[u]) + 1;
        }
        if (A[v] < 0) {
            // single node with computer -> sum negative -> actually disabled
            // So for dp_on this is invalid
        } else {
            // single node battery -> no computer -> not active
        }
        // The above is already covered by bestOff calculation

        // Ensure dp_off is min of possibilities
        // Also we need sum_on and hasComp for parent
        sum_on[v] = bestOnSum;
        hasComp[v] = bestOnHasComp;
        // But if dp_on[v] is INF, we shouldn't present an active component to parent
        // Actually sum_on and hasComp are used only if parent keeps us merged as disabled child.
        // For disabled child, these values represent what the component actually is.
        // So they are correct as computed.
        // However if no valid dp_on but we still have sum and hasComp, it's fine for parent's merging.
    }
