                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static int N;
    static long[] A;
    static ArrayList<Integer>[] g;
    static int[] parent;
    static int[] order;

    static final int INF = 1_000_000_000;

    // DP arrays:
    // keep0[v]: minimum cuts inside subtree of v so that component containing v
    //           (within subtree) has no computer => all positive, thus sum>0
    // keepNeg[v]: minimum cuts inside subtree of v so that component containing v
    //             has at least one computer and total sum < 0
    // cutAll[v]: minimum cuts inside subtree of v so that every component is already disabled
    static int[] keep0, keepNeg, cutAll;
    static long[] sumPos, sumAll;
    static boolean[] hasNeg;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        N = fs.nextInt();
        A = new long[N + 1];
        for (int i = 1; i <= N; i++) A[i] = fs.nextLong();

        g = new ArrayList[N + 1];
        for (int i = 1; i <= N; i++) g[i] = new ArrayList<>();
        for (int i = 0; i < N - 1; i++) {
            int u = fs.nextInt();
            int v = fs.nextInt();
            g[u].add(v);
            g[v].add(u);
        }

        parent = new int[N + 1];
        order = new int[N];
        buildOrder(1);

        keep0 = new int[N + 1];
        keepNeg = new int[N + 1];
        cutAll = new int[N + 1];
        sumPos = new long[N + 1];
        sumAll = new long[N + 1];
        hasNeg = new boolean[N + 1];

        for (int idx = N - 1; idx >= 0; idx--) {
            int v = order[idx];

            // cut all children away
            int baseCut = 0;
            for (int to : g[v]) {
                if (to == parent[v]) continue;
                baseCut += cutAll[to] + 1;
            }

            // keep0: component containing v has no computer => every kept node positive
            if (A[v] > 0) {
                int cost = baseCut;
                long s = A[v];
                for (int to : g[v]) {
                    if (to == parent[v]) continue;
                    // Either cut edge, or keep child in keep0 state
                    int cutCost = cutAll[to] + 1;
                    int keepCost = keep0[to];
                    if (keepCost < cutCost) {
                        cost += keepCost - cutCost;
                        s += sumPos[to];
                    }
                }
                keep0[v] = cost;
                sumPos[v] = s;
            } else {
                keep0[v] = INF;
                sumPos[v] = 0;
            }

            // keepNeg: component containing v has at least one computer and total sum < 0
            // We start with only v and optionally merge children in keep0/keepNeg state,
            // or cut them.
            HashMap<Long, Integer> dp = new HashMap<>();
            if (A[v] < 0) {
                dp.put(A[v], 0);
            }

            for (int to : g[v]) {
                if (to == parent[v]) continue;
                HashMap<Long, Integer> ndp = new HashMap<>();

                int cutCost = cutAll[to] + 1;
                for (Map.Entry<Long, Integer> e : dp.entrySet()) {
                    long curSum = e.getKey();
                    int curCost = e.getValue();

                    // cut this child
                    putMin(ndp, curSum, curCost + cutCost);

                    // keep child as all-positive component merged
                    if (keep0[to] < INF) {
                        putMin(ndp, curSum + sumPos[to], curCost + keep0[to]);
                    }

                    // keep child as negative-capable disabled component merged
                    if (keepNeg[to] < INF) {
                        putMin(ndp, curSum + sumAll[to], curCost + keepNeg[to]);
                    }
                }
                dp = ndp;
            }

            int bestNeg = INF;
            long bestSum = 0;
            for (Map.Entry<Long, Integer> e : dp.entrySet()) {
                long s = e.getKey();
                if (s < 0 && e.getValue() < bestNeg) {
                    bestNeg = e.getValue();
                    bestSum = s;
                }
            }
            keepNeg[v] = bestNeg;
            sumAll[v] = bestSum; // one representative sum for transitions

            // For transitioning parent with keepNeg[v], we actually need the possibility
            // of choosing different negative sums. A single representative is insufficient.
            // So we must compute cutAll immediately using full dp, and store richer info.
            // To keep correctness, we replace the above simplified approach with exact
            // per-node frontier DP stored compactly.
        }

        // Exact solution using frontier maps per node
        solveExact();

    }

    static void solveExact() throws Exception {
        // Recompute with exact state maps:
        @SuppressWarnings("unchecked")
        HashMap<Long, Integer>[] negMap = new HashMap[N + 1];

        keep0 = new int[N + 1];
        cutAll = new int[N + 1];
        sumPos = new long[N + 1];

        for (int idx = N - 1; idx >= 0; idx--) {
            int v = order[idx];

            int baseCut = 0;
            for (int to : g[v]) {
                if (to == parent[v]) continue;
                baseCut += cutAll[to] + 1;
            }

            if (A[v] > 0) {
                int cost = baseCut;
                long s = A[v];
                for (int to : g[v]) {
                    if (to == parent[v]) continue;
                    int cutCost = cutAll[to] + 1;
                    int keepCost = keep0[to];
                    if (keepCost < cutCost) {
                        cost += keepCost - cutCost;
                        s += sumPos[to];
                    }
                }
                keep0[v] = cost;
                sumPos[v] = s;
            } else {
                keep0[v] = INF;
                sumPos[v] = 0;
            }

            HashMap<Long, Integer> dp = new HashMap<>();
            if (A[v] < 0) dp.put(A[v], 0);

            for (int to : g[v]) {
                if (to == parent[v]) continue;
                HashMap<Long, Integer> ndp = new HashMap<>();

                int cutCost = cutAll[to] + 1;
                for (Map.Entry<Long, Integer> e : dp.entrySet()) {
                    long curSum = e.getKey();
                    int curCost = e.getValue();

                    putMin(ndp, curSum, curCost + cutCost);

                    if (keep0[to] < INF) {
                        putMin(ndp, curSum + sumPos[to], curCost + keep0[to]);
                    }

                    HashMap<Long, Integer> childNeg = negMap[to];
                    if (childNeg != null) {
                        for (Map.Entry<Long, Integer> ce : childNeg.entrySet()) {
                            putMin(ndp, curSum + ce.getKey(), curCost + ce.getValue());
                        }
                    }
                }
                dp = compress(dp = ndp);
            }

            negMap[v] = new HashMap<>();
            int bestDisabled = INF;

            // If v's component is disabled by negative sum
            for (Map.Entry<Long, Integer> e : dp.entrySet()) {
                if (e.getKey() < 0) {
                    putMin(negMap[v], e.getKey(), e.getValue());
                    if (e.getValue() < bestDisabled) bestDisabled = e.getValue();
                }
            }

            // cutAll[v]: either whole component containing v is all-positive, or negative-sum
            if (keep0[v] < bestDisabled) bestDisabled = keep0[v];
            cutAll[v] = bestDisabled;
        }

        System.out.println(cutAll[1]);
    }

    static HashMap<Long, Integer> compress(HashMap<Long, Integer> map) {
        // Remove dominated states:
        // For sums sorted ascending, keep only states with strictly improving cost.
        if (map.isEmpty()) return map;
        ArrayList<Map.Entry<Long, Integer>> list = new ArrayList<>(map.entrySet());
        list.sort(Comparator.comparingLong(Map.Entry::getKey));

        HashMap<Long, Integer> res = new HashMap<>();
        int best = INF;
        for (Map.Entry<Long, Integer> e : list) {
            int c = e.getValue();
            if (c < best) {
                best = c;
                res.put(e.getKey(), c);
            }
        }
        return res;
    }

    static void putMin(HashMap<Long, Integer> map, long key, int val) {
        Integer old = map.get(key);
        if (old == null || val < old) map.put(key, val);
    }

    static void buildOrder(int root) {
        int idx = 0;
        int[] stack = new int[N];
        stack[idx++] = root;
        parent[root] = 0;
        int ord = 0;
        while (idx > 0) {
            int v = stack[--idx];
            order[ord++] = v;
            for (int to : g[v]) {
                if (to == parent[v]) continue;
                parent[to] = v;
                stack[idx++] = to;
            }
        }
    }
